/* nbh-learn-units-e4.js (v26.01): written units of the Learning page, section E (Behavior-change interventions), units e11 to
   e13. The shape of a unit is described in nbh-learn-units.js. The people in every example are invented. */
window.NBH_LEARN_UNITS = window.NBH_LEARN_UNITS || {};
Object.assign(window.NBH_LEARN_UNITS, {
  e11: {
    aim: [
      'Define shaping and tell it apart from chaining and from prompt fading.',
      'Reinforce the current approximation and stop reinforcing earlier ones.',
      'Move to the next step at the right time, and step back when the behavior falls apart.',
      'Recognize how problem behavior gets shaped by accident.'
    ],
    lesson: [
      { h: 'Building a behavior that does not exist yet',
        p: ['You cannot reinforce a behavior that never happens. Shaping gets round this by reinforcing something the student already does that is a little like the goal, then something a little closer, and closer again, until the goal behavior itself appears.',
            'The technical description is differential reinforcement of successive approximations. Each approximation is reinforced until it is steady; then the reinforcer is kept for the next, closer one, and the earlier one no longer earns it.'],
        key: ['The goal: the terminal behavior.', 'The steps toward it: successive approximations.', 'Reinforce the current step; stop reinforcing the ones before it.'],
        check: { q: 'In shaping, what happens to an earlier approximation once the student is working on the next one?',
          opts: ['It is still reinforced every time.', 'It is punished.', 'It is no longer reinforced.', 'It is prompted.'],
          a: 2, why: 'Withholding the reinforcer for the earlier form is what moves the behavior forward.' } },
      { h: 'What can be shaped',
        p: ['Shaping can change the form of a behavior: a sound becomes a syllable, a syllable a word. It can also change how much of it there is: how long a student stays in the seat, how loudly he speaks, how quickly she starts, how many bites are eaten, how close a child will come to a feared thing.',
            'In each case there is one behavior changing along one dimension, step by step.'],
        check: { q: 'A student who speaks in a whisper is reinforced for speaking slightly louder, then louder again, until he can be heard across the table. What is being shaped?',
          opts: ['The topic of his speech.', 'How loud it is.', 'The number of words.', 'His eye contact.'],
          a: 1, why: 'One dimension of the behavior, its loudness, changes by steps.' } },
      { h: 'Shaping is not chaining or prompt fading',
        p: ['In chaining, several different behaviors are linked in order: tap on, hands wet, soap. In shaping, one behavior changes form or amount. In prompt fading, the behavior stays the same from the first day and it is the help that changes.',
            'The three are often used together. A step in a chain may need shaping, and prompts may be used to get an approximation started.'],
        check: { q: 'On day 1 a child is reinforced for touching a toothbrush, later for holding it, later for bringing it to her mouth, and at last for brushing. This is:',
          opts: ['Prompt fading', 'Chaining', 'Shaping', 'Extinction alone'],
          a: 2, why: 'Closer and closer approximations of one goal behavior are reinforced in turn.' } },
      { h: 'Running a shaping step',
        p: ['Your supervisor defines the goal, picks a starting behavior that already happens, and lists the steps between. Your plan tells you which step is current and what counts as meeting it.',
            'Watch closely and reinforce at the very instant the current approximation occurs. Timing matters more here than anywhere: a reinforcer one second late may land on something else. Do not reinforce earlier approximations any more, and do reinforce anything better than the current step.',
            'Sessions are short and upbeat. A student who is earning often is a student who keeps trying.'],
        check: { q: 'The current step is “says ‘ba’ for ball”. The student says a clear “ball”. You:',
          opts: ['Reinforce it at once.', 'Withhold the reinforcer: it is not the current step.', 'Ask for “ba”.', 'Ignore it.'],
          a: 0, why: 'A response better than the current step is always reinforced. The steps are a floor, not a ceiling.' } },
      { h: 'Moving on, and moving back',
        p: ['Move to the next step when the plan’s criterion is met, for example the current step on 8 of 10 chances. Moving too soon makes the behavior fall apart, because the next step is out of reach. Staying too long fixes the behavior at that step and makes the next one harder.',
            'If the student stops succeeding after a move, the step was too big. Go back to the last step that worked, get it steady again, and tell your supervisor, who can put a smaller step in between.',
            'Record which approximation was reinforced on each trial, not only “correct”.'],
        check: { q: 'After the step is raised, the student gets no reinforcers for five minutes and starts to cry. What is the best move?',
          opts: ['Wait until he manages the new step.', 'End shaping for good.', 'Give free reinforcers.', 'Go back to the last step he could do, reinforce it, and tell your supervisor the step was too large.'],
          a: 3, why: 'No reinforcement means no learning. A smaller step is needed.' } },
      { h: 'Shaping by accident',
        p: ['Shaping works whether or not anyone means it to. A parent who ignores quiet asking, gives in to whining, later holds out against whining and gives in to shouting, has reinforced closer and closer approximations of a scream.',
            'This is why you never “give in at the peak” during a plan, and why a slow rise in the intensity of a behavior is always worth reporting. Somewhere, the stronger form is paying.'],
        check: { q: 'Over a month, a student’s way of getting the teacher’s help has gone from raising a hand, to calling out, to banging the desk. The most likely explanation is that:',
          opts: ['He is growing.', 'The quieter forms stopped working and the louder ones were reinforced.', 'He has forgotten how to raise his hand.', 'It is a coincidence.'],
          a: 1, why: 'Reinforcement moved, step by step, to louder behavior. That is shaping, unplanned.' } }
    ],
    watch: [
      { k: 'shape_work', c: 1, look: 'What makes a stretch of work earn a token, and how that mark moves as she improves.' },
      { k: 'shape_dist', look: 'The one thing that changes from session to session, and what the adult does when she steps away.' },
      { k: 'shape_fast', look: 'How the time limit is set for the next session, and why correct answers earn tokens too.' }
    ],
    examples: {
      ask: 'Which procedure is this?',
      intro: 'Ten descriptions. Decide whether each is shaping, chaining or prompt fading.',
      opts: ['Shaping', 'Chaining', 'Prompt fading'],
      items: [
        { s: 'Reinforcers are given first for looking at the pool, then for standing at the edge, then for a foot in the water, then for getting in.', a: 0, why: 'Closer approximations of one goal behavior.' },
        { s: 'Hana is taught to turn on the tap, wet her hands, use soap, rinse and dry, in that order.', a: 1, why: 'Different behaviors linked in sequence.' },
        { s: 'Ian zips his coat correctly from the first day; the adult’s help goes from hand over hand, to a touch, to nothing.', a: 2, why: 'The behavior stays the same and the help is reduced.' },
        { s: 'A reinforcer follows sitting for 10 seconds, then 20, then 40, then a minute.', a: 0, why: 'One behavior is extended step by step.' },
        { s: 'A dotted outline of the letter A gets fainter each week until Jai writes it with no outline.', a: 2, why: 'The added help in the materials is faded.' },
        { s: 'Kim learns to take a tray, choose food, pay and sit down, taught one step at a time.', a: 1, why: 'Linked steps of a routine.' },
        { s: 'Any sound is reinforced at first, then only “m”, then “mi”, then “milk”.', a: 0, why: 'Successive approximations of a word.' },
        { s: 'The teacher’s point toward the bin becomes a glance, then nothing, while Leo throws away his cup each time.', a: 2, why: 'The gesture is faded; the behavior was there throughout.' },
        { s: 'Mia is praised for answering within 30 seconds, then only within 15, then only within 5.', a: 0, why: 'Latency is shaped downward.' },
        { s: 'Ned learns the first step of tying his shoes, then the first two, then the first three.', a: 1, why: 'Forward chaining of a task.' }
      ]
    },
    practice: {
      title: 'Shape a clear “juice”',
      intro: 'You are shaping the word “juice” with Omar, a simulated student, at snack. Read the plan, then decide.',
      plan: ['Goal: says “juice” clearly to ask for juice.', 'Steps: 1 any sound while looking at the juice; 2 “j” or “joo”; 3 “joos”; 4 “juice”.', 'Current step: 2. Give a sip of juice at once for step 2 or better. Nothing for step 1 any more.', 'Move up after 8 of 10 chances at the current step. If he fails 5 chances in a row after a move, go back one step.', 'Record the step reached on each chance.'],
      steps: [
        { t: 'Chance 1', see: 'Omar looks at the juice and says, “Aah.”', opts: ['Give a sip: he tried.', 'Wait, with the juice in view, and say nothing about it.', 'Say, “No, say joo.”'], a: 1, why: '“Aah” is step 1, which no longer earns juice. The reprimand is not in the plan.' },
        { t: 'Chance 1', see: 'A few seconds later he says, “Joo.”', opts: ['Give a sip at once.', 'Wait for “juice”.', 'Give the whole cup.'], a: 0, why: 'He met the current step. The reinforcer is immediate and small, so there are many chances.' },
        { t: 'Chance 4', see: 'Omar says, “Juice,” quite clearly.', opts: ['Wait: the current step is only “joo”.', 'Give a sip at once, and record step 4.', 'Ask him to say it again first.'], a: 1, why: 'Better than the current step is always reinforced, and the record shows what he can do.' },
        { t: 'Chance 10', see: 'Your record for this session: step 2 or better on 9 of 10 chances.', opts: ['Stay at step 2 for another week to be safe.', 'Move to step 3 next session, as the plan says, and tell your supervisor.', 'Jump to step 4.'], a: 1, why: 'The criterion is met. Staying too long fixes “joo” in place; jumping risks a step that is too big.' },
        { t: 'Next session', see: 'Current step is now 3, “joos”. Omar says, “Joo.”', opts: ['Give a sip: it earned juice yesterday.', 'Wait for a closer attempt.', 'Go back to step 2 at once.'], a: 1, why: 'The earlier approximation no longer earns the reinforcer. One miss is not a reason to go back.' },
        { t: 'Five chances later', see: 'Omar has said “joo” five times, had no juice, and is pushing his cup away.', opts: ['Keep waiting.', 'Give him the juice for nothing.', 'Go back to step 2, reinforce “joo”, and tell your supervisor the step may be too big.'], a: 2, why: 'The plan’s rule for stepping back has been reached. The supervisor may add a step between.' },
        { t: 'At home time', see: 'Omar’s father says, “At home he just screams and we give him the juice.”', opts: ['Tell him to stop doing that.', 'Thank him, and pass it to your supervisor the same day.', 'Say nothing to anyone.'], a: 1, why: 'Screaming is being reinforced at home while a word is shaped at school. The supervisor works with the family.' },
        { t: 'End of the week', see: 'How do you report the week?', opts: ['“He is doing well.”', '“Step 2 met on Monday (9 of 10). Step 3 tried on Tuesday: 5 misses in a row, back to step 2. One clear ‘juice’ on Monday. Father reports screaming for juice at home.”', '“He cannot say juice.”'], a: 1, why: 'The steps reached, the move back, the best response and the news from home.' }
      ]
    },
    quiz: { pass: 80, draw: 10, items: [
      { q: 'Shaping is the differential reinforcement of:', opts: ['Incompatible behavior.', 'Successive approximations of a goal behavior.', 'Low rates.', 'Other behavior.'], a: 1, why: 'Closer and closer steps toward the goal.' },
      { q: 'The goal of a shaping program is called the:', opts: ['Terminal behavior.', 'Baseline.', 'Approximation.', 'Prompt.'], a: 0, why: 'It is where the steps end.' },
      { q: 'Shaping is used when the goal behavior:', opts: ['Happens often.', 'Is dangerous.', 'Does not yet occur.', 'Is a chain.'], a: 2, why: 'It builds something new out of what the student already does.' },
      { q: 'When a new step becomes current, the previous step is:', opts: ['Reinforced twice as much.', 'Prompted.', 'Punished.', 'No longer reinforced.'], a: 3, why: 'Extinction of the earlier form moves the behavior on.' },
      { q: 'A response better than the current step is:', opts: ['Ignored.', 'Reinforced.', 'Corrected.', 'Scored as an error.'], a: 1, why: 'The current step is the least that earns the reinforcer.' },
      { q: 'Moving through the steps too quickly tends to:', opts: ['Make the behavior break down.', 'Speed up mastery.', 'Have no effect.', 'Fix the behavior at an early step.'], a: 0, why: 'The next step is out of reach and reinforcement stops.' },
      { q: 'Staying too long at one step tends to:', opts: ['Make the next step easier.', 'Have no effect.', 'Fix the behavior at that step.', 'End the program.'], a: 2, why: 'The approximation becomes hard to move.' },
      { q: 'In shaping, the reinforcer should be delivered:', opts: ['At the end of the session.', 'After a pause.', 'By someone else.', 'At the instant the approximation occurs.'], a: 3, why: 'A late reinforcer may strengthen something else.' },
      { q: 'Increasing the time a student stays on task from 1 minute to 10 by small steps is shaping of:', opts: ['Topography', 'Duration', 'Latency', 'Volume'], a: 1, why: 'How long the behavior lasts.' },
      { q: 'The difference between shaping and chaining is that:', opts: ['Shaping changes one behavior by steps; chaining links several behaviors in order.', 'They are the same.', 'Chaining uses no reinforcement.', 'Shaping is only for speech.'], a: 0, why: 'One behavior changing, against several behaviors linked.' },
      { q: 'After a step is raised, the student fails several times in a row. You:', opts: ['Keep waiting.', 'Stop the session and the program.', 'Go back to the last successful step and tell your supervisor.', 'Give a reprimand.'], a: 2, why: 'The step was too large.' },
      { q: 'Who sets the steps of a shaping program?', opts: ['The technician, session by session.', 'The student.', 'The parent alone.', 'The supervisor.'], a: 3, why: 'You run the current step and report.' },
      { q: 'Problem behavior can be shaped by accident when:', opts: ['Adults always respond to quiet requests.', 'Adults give in only when the behavior gets more intense.', 'No one reinforces anything.', 'Data are taken.'], a: 1, why: 'Reinforcement moves to stronger and stronger forms.' },
      { q: 'Shaping data should show:', opts: ['Which approximation was reinforced on each trial.', 'Only the number of reinforcers.', 'Only the session length.', 'Nothing.'], a: 0, why: 'Progress is movement through the steps.' }
    ] },
    role: [
      { t: 'The shaping game', setup: 'The trainer thinks of a simple action (for example, touching the door handle). The trainee, without speaking or pointing, shapes it using only a click or the word “yes”. Then they swap and the trainee writes down the steps they used.',
        steps: ['Starts by reinforcing a behavior that is already happening.', 'Delivers the click at the instant of the approximation.', 'Stops clicking for earlier approximations once a closer one appears.', 'Reinforces anything better than the current step.',
                'Goes back a step when the “learner” stalls.', 'Uses no words, gestures or prompts.'] },
      { t: 'A written shaping step', setup: 'The trainer plays a student whose voice is to be shaped from a whisper to conversation level in four steps. The current step and the criterion are on a card.',
        steps: ['Reinforces the current step at once.', 'Gives nothing for the earlier step.', 'Reinforces a better response.', 'Records the step reached on each chance.', 'Says when they would move on or step back, by the criterion.'] }
    ],
    roleRule: 'Met when the goal action is reached in the game and the written step is run with every part in place.',
    discuss: [
      'What did the shaping game teach you about timing?',
      'Think of a behavior that has grown louder or stronger over time in someone you know. What might have shaped it?',
      'How do you keep a student earning often when the steps are small?'
    ],
    read: [
      'Cooper, J. O., Heron, T. E., & Heward, W. L. (2020). Applied behavior analysis (3rd ed.). Pearson. The chapter on shaping.',
      'Horner, R. D. (1971). Establishing use of crutches by a mentally retarded spina bifida child. Journal of Applied Behavior Analysis, 4(3), 183–189.',
      'Ghaemmaghami, M., Hanley, G. P., Jessel, J., & Landa, R. (2018). Shaping complex functional communication responses. Journal of Applied Behavior Analysis, 51(3), 502–520.'
    ]
  },

  e12: {
    aim: [
      'Explain how changing what comes before a behavior can make the behavior unnecessary.',
      'Run noncontingent reinforcement on its schedule.',
      'Run a high-probability request sequence.',
      'Offer choices, use schedules and warnings, and carry out changes to demands and tasks as the plan describes.'
    ],
    lesson: [
      { h: 'Working before the behavior',
        p: ['Most of this section has been about consequences. Antecedent interventions work on the other side: they change what is going on before the behavior, so that the problem behavior is less likely to happen in the first place.',
            'They are usually calm to run and easy to accept, and because they prevent a behavior and do not react to it, nobody has to get through the behavior first. They are often combined with teaching a replacement, since prevention by itself teaches no new skill.'],
        check: { q: 'An antecedent intervention is one that:',
          opts: ['Follows the problem behavior.', 'Changes conditions before the behavior so that it is less likely.', 'Removes a privilege.', 'Is used only in a crisis.'],
          a: 1, why: 'It acts before the behavior, on the situation that gives rise to it.' } },
      { h: 'Why wanting changes',
        p: ['How much a consequence is worth changes from hour to hour. After a long stretch with no adult attention, attention is worth a great deal, and whatever has brought attention before becomes likely. After plenty of attention, it is worth little. The same goes for food, for breaks and for favorite things.',
            'Events that change the value of a consequence in this way are called motivating operations. Many antecedent interventions work by changing them: give enough of the reinforcer for free, or make the task less unpleasant, and the reason for the problem behavior shrinks.'],
        check: { q: 'A student who has just had ten minutes of one-to-one play with the teacher is, for a while, less likely to act up for attention because:',
          opts: ['He has been warned.', 'He is tired.', 'Attention is worth less to him just now.', 'He has forgotten how.'],
          a: 2, why: 'Having had plenty lowers the value of more, and with it the behavior that gets it.' } },
      { h: 'Noncontingent reinforcement',
        p: ['In noncontingent reinforcement (NCR) the reinforcer that has kept the problem behavior going is given on a time schedule, whatever the student is doing: a minute of attention every five minutes, a short break every ten, a turn with the item every three.',
            'Because it comes for free and often, the student has less reason to work for it with problem behavior. The schedule starts dense, more often than the behavior usually happens, and is thinned slowly by the supervisor.',
            'Your part is the timer. Deliver on time, every time, in the amount the plan says, and do not make it depend on good behavior: that would be a different procedure. Some plans add a rule for a delivery that falls due in the middle of problem behavior, such as waiting a set number of seconds after it stops. Follow what yours says.'],
        key: ['On the clock, not on the behavior.', 'Dense at first, thinned later.', 'Use a timer.'],
        check: { q: 'The NCR timer sounds for Aida’s minute of attention. She has not done any work for the last five minutes. You:',
          opts: ['Withhold it until she works.', 'Give it, as the schedule says.', 'Give half.', 'Lecture her first.'],
          a: 1, why: 'Noncontingent means it does not depend on what she did. Making it depend on work turns it into something else.' } },
      { h: 'High-probability request sequence',
        p: ['Some instructions are nearly always followed (“Give me five”, “Touch your nose”) and some rarely are (“Put the toys away”). In a high-probability request sequence you give three to five of the easy ones quickly, praising each, and then, within a few seconds, the hard one.',
            'Following has momentum. A student who has just followed three instructions and been praised three times is more likely to follow the fourth.',
            'Details matter: the easy requests must really be easy for this student, the praise must be quick, the hard request must follow within about five seconds of the last praise, and following the hard one is reinforced. Do not use the sequence right after problem behavior, or it becomes a reward for it.'],
        check: { q: 'In a high-probability sequence, how soon after praising the last easy request is the hard request given?',
          opts: ['After a break of a minute.', 'At the end of the lesson.', 'When the student asks.', 'Within a few seconds.'],
          a: 3, why: 'The momentum fades quickly; the plan usually says within 5 seconds.' } },
      { h: 'Choice',
        p: ['Being told exactly what to do, how and when is, for many students, the thing that sets off problem behavior. Offering a choice changes that without changing the work: which of two tasks first, pencil or pen, at the desk or on the floor, with which partner.',
            'Offer the choices the plan lists, honor the one that is made, and make both options acceptable to you. Some plans let the student switch tasks part-way, and then you let them. “Do you want to do your math?” is not a choice unless “no” will be accepted.'],
        check: { q: 'Which is a real choice of the kind a plan would write?',
          opts: ['“Do you want to work or lose recess?”', '“Are you going to behave?”', '“Would you like to do the spelling first or the math first?”', '“Do you want to do your work?”'],
          a: 2, why: 'Both options are acceptable, and whichever is chosen can be honored.' } },
      { h: 'Making demands and tasks easier to meet',
        p: ['When problem behavior is a way out of work, the work can be changed. In demand fading, demands are reduced to very few and then added back slowly as the student succeeds. In interspersal, easy items are mixed in before or among hard ones. A task can be shortened, broken into parts, or given with an aid such as a number line or a word bank.',
            'These are changes to how the task is presented, not to what the student is expected to learn in the end. The plan says exactly how many demands, which items and which aid. A kind impulse to cut the work further than the plan says can stall the fading.'],
        check: { q: 'A plan says: “This week, 3 problems per sitting; next week 5 if there has been no problem behavior.” This is:',
          opts: ['Demand fading', 'Noncontingent reinforcement', 'A high-probability sequence', 'Extinction'],
          a: 0, why: 'Demands are started low and added back step by step.' } },
      { h: 'Schedules, warnings and timers',
        p: ['Not knowing what is coming, or having something enjoyable end without notice, sets off a great deal of behavior. A visual schedule shows what will happen and in what order. A first-then board shows the task and what follows it. A warning (“Two more minutes with the blocks”) and a visible timer make the end of an activity predictable.',
            'Use them the way the plan says and mean them. A warning that is followed by five more warnings teaches the student to wait for the sixth. When the timer ends, the activity ends, calmly, and the schedule is checked for what is next.'],
        check: { q: 'The two-minute warning has been given and the timer has now ended. The student says, “One more minute!” The plan does not mention extensions. You:',
          opts: ['Give one more minute.', 'Give five more, as a treat.', 'End the activity calmly and point to what is next on the schedule.', 'Argue about fairness.'],
          a: 2, why: 'A timer that can be bargained with stops being a signal.' } },
      { h: 'The room itself',
        p: ['Some antecedents are physical: seating away from a noisy door or a tempting shelf, less clutter on the table, headphones in the cafeteria, a place in the line that is not next to a particular classmate.',
            'You will often be the first to notice what sets a behavior off. You do not rearrange the plan, but you do report: “It happens when the hand dryer goes off”, “It happens when he sits beside the window.” That is how such changes get made.'],
        check: { q: 'You notice that a student’s shouting nearly always starts when the classroom door is left open to the corridor. You:',
          opts: ['Tell your supervisor what you have observed.', 'Say nothing: it is not in the plan.', 'Lock the door.', 'Move the student to another class.'],
          a: 0, why: 'Your observation of what comes before the behavior is exactly what the supervisor needs.' } },
      { h: 'Doing them well',
        p: ['Antecedent procedures look simple, which is why they slip. The timer is forgotten once teaching gets busy. The easy requests become whatever comes to mind. The choice is offered in a tone that makes one option wrong.',
            'Keep the timer where you see it. Keep the list of easy requests and the choice menu with the plan. Record each delivery and each sequence, along with the problem behavior. And when problem behavior does happen, do what the plan says for it: the antecedent procedure does not replace that.'],
        check: { q: 'During a busy lesson you realize you have missed two NCR deliveries. You:',
          opts: ['Give three at once to catch up.', 'Say nothing and carry on as if they had been given.', 'Restart the schedule now, and record the two that were missed.', 'Stop NCR for the day.'],
          a: 2, why: 'The record has to show what the student actually received. Piling up deliveries is not the schedule either.' } }
    ],
    watch: [
      { k: 'ncr_attention', c: 1, look: 'What the timer is for, and that the comments come whatever the student is doing.' },
      { k: 'ncr_work', c: 1, look: 'What is given on the timer during work, and how the breaks are timed.' },
      { k: 'a_highp', c: 1, look: 'The three easy requests, the quick praise, and how soon the hard request follows.' },
      { k: 'choice-academic-task-escape', c: 1, look: 'What is offered, how the choice is honored, and what happens when he asks to switch.' },
      { k: 'ante_fade', c: 1, look: 'How few demands there are at the start, and how they are added back.' },
      { k: 'ante_mix', c: 1, look: 'Where the easy items are placed in relation to the hard ones.' },
      { k: 'ncr_items', look: 'The signal that the item is coming, and how a request is added later.' },
      { k: 'ncr_between', look: 'Free access before an activity, and the signaled breaks from it.' },
      { k: 'a_highp_praise', look: 'The sequence with praise as the only reinforcer.' },
      { k: 'a_highp_class', look: 'The sequence given to a whole class before a transition.' },
      { k: 'a_highp_seatwork', look: 'The sequence used just before independent work.' },
      { k: 'a_highp_peer', look: 'A classmate giving the easy requests.' },
      { k: 'ante_task', look: 'The aid that is added to the hard work, and what stays the same.' },
      { k: 'ee_match', look: 'How the adult finds out whether the items really match: the three parts of the check.' },
      { k: 'ee_turn', look: 'When the item is changed, and what the adult does about the stereotypy itself.' },
      { k: 'ee_hands', look: 'The three rules for the object, and what the adult says about it during the lesson.' }
    ],
    examples: {
      ask: 'Which antecedent intervention is this?',
      intro: 'Twelve short descriptions. Decide which kind of antecedent intervention each one is.',
      opts: ['Noncontingent reinforcement', 'High-probability request sequence', 'Choice', 'A change to the task or the demands', 'A schedule, warning or timer'],
      items: [
        { s: 'Every four minutes the aide sits with Abe for 30 seconds and chats, whatever he is doing.', a: 0, why: 'The reinforcer comes on the clock.' },
        { s: '“Clap. Touch your head. High five. Great! Now open your book.”', a: 1, why: 'Easy requests, then the hard one.' },
        { s: 'Bea is asked whether she wants to write with the blue pen or the pencil.', a: 2, why: 'Two acceptable options.' },
        { s: 'A strip of pictures on Cy’s desk shows: reading, snack, math, playground.', a: 4, why: 'A visual schedule.' },
        { s: 'Dov’s worksheet has two easy sums before each hard one.', a: 3, why: 'Interspersal of easy items.' },
        { s: '“Five more minutes on the swing,” and a sand timer is turned over.', a: 4, why: 'A warning made visible.' },
        { s: 'A favorite toy is handed to Eve for one minute every five minutes during circle time.', a: 0, why: 'Time-based access to an item.' },
        { s: 'In the first week Finn is asked to do one page; a page is added each week.', a: 3, why: 'Demand fading.' },
        { s: 'Gia picks which of three assignments to do, and may change her mind once.', a: 2, why: 'Choice of task.' },
        { s: 'A classmate asks Hal to pass the glue, hold the paper and press it down, each with a “Thanks!”, before the teacher asks him to tidy up.', a: 1, why: 'A high-probability sequence, given by a peer.' },
        { s: 'A card on the desk reads: “First writing, then computer.”', a: 4, why: 'A first-then board.' },
        { s: 'Ivy is given a multiplication chart to use during the hard problems.', a: 3, why: 'An aid added to the task.' }
      ]
    },
    practice: {
      title: 'A morning of prevention',
      intro: 'You work with Jude, a simulated student whose shouting is kept going partly by attention and partly by escape from writing. Read the plan, then decide.',
      plan: ['NCR: 30 seconds of attention every 4 minutes, on the timer, whatever Jude is doing. If he is shouting when it sounds, deliver 10 seconds after he stops.', 'Before writing: three easy requests from the list (high five; touch your nose; pass me the pencil), praise each, then “Start your writing” within 5 seconds. Praise starting.', 'Writing: Jude chooses pencil or pen, and desk or floor cushion. 3 sentences this week.', 'Two-minute warning with the visual timer before free time ends.', 'Shouting: no comment; point to his “I need help” card. Record it.'],
      steps: [
        { t: '9:00', see: 'The session starts. Jude is looking at a book.', opts: ['Start the 4-minute timer.', 'Wait for him to need attention.', 'Tell him he will get attention if he is good.'], a: 0, why: 'NCR runs from the start, on the clock. A promise tied to being good would make it contingent.' },
        { t: '9:04', see: 'The timer sounds. Jude has been reading quietly.', opts: ['Skip it: he is fine.', 'Sit with him for 30 seconds and chat, then reset the timer.', 'Give him a sticker for reading.'], a: 1, why: 'Deliveries are not skipped when things are going well. That is when they keep things going well.' },
        { t: '9:08', see: 'The timer sounds. Jude is shouting across the room.', opts: ['Deliver the attention now.', 'Cancel this delivery.', 'Wait until he has stopped for 10 seconds, then deliver.'], a: 2, why: 'His plan has a rule for this, so that attention does not follow shouting directly.' },
        { t: '9:15', see: 'Free time has two minutes left.', opts: ['Say nothing and end it when the time is up.', 'Give the two-minute warning and start the visual timer.', 'End it now to save time.'], a: 1, why: 'The warning makes the ending predictable.' },
        { t: '9:17', see: 'The timer ends. Jude says, “Not yet!”', opts: ['Give two more minutes.', 'End free time calmly and show the schedule: writing is next.', 'Explain why time is up, at length.'], a: 1, why: 'The timer means what it says, and the schedule shows what follows.' },
        { t: '9:18', see: 'It is time for the high-probability sequence.', opts: ['“High five! Touch your nose! Pass me the pencil!”, with praise after each, then “Start your writing.”', '“Jump ten times. Spell your surname. Now start your writing.”', '“Start your writing,” three times.'], a: 0, why: 'The easy requests come from his list, each praised, with the hard one straight after.' },
        { t: '9:18', see: 'You have praised the third easy request. Your pen has rolled under the table.', opts: ['Fetch the pen, then give the writing instruction.', 'Say “Start your writing” now; the pen can wait.', 'Start the sequence again later.'], a: 1, why: 'The hard request must follow within 5 seconds of the last praise.' },
        { t: '9:19', see: 'Jude picks up the pen and writes one word.', opts: ['Praise him for starting.', 'Say nothing until he has finished all three sentences.', 'Tell him the pencil would be neater.'], a: 0, why: 'Starting is what the sequence is for, and the plan praises it. Pen or pencil is his choice.' },
        { t: '9:24', see: 'After two sentences Jude shouts, “This is stupid!”', opts: ['“We do not shout.”', 'Reduce the work to two sentences.', 'Say nothing and point to his “I need help” card. Record it.'], a: 2, why: 'The plan’s response to shouting still applies. Cutting the work would let shouting end it.' },
        { t: 'End of the morning', see: 'Twelve NCR deliveries were due. You gave ten; two were missed while you were setting up the writing.', opts: ['Record 12 of 12.', 'Record 10 of 12, with the reason.', 'Record nothing about NCR.'], a: 1, why: 'What the student actually received is part of the data, and the reason shows the supervisor where the plan is hard to run.' }
      ]
    },
    quiz: { pass: 80, draw: 12, items: [
      { q: 'Antecedent interventions act:', opts: ['After the behavior.', 'Before the behavior.', 'Only at home.', 'Only in a crisis.'], a: 1, why: 'They change the conditions that lead to the behavior.' },
      { q: 'A motivating operation is an event that:', opts: ['Changes how much a consequence is worth for a time.', 'Punishes behavior.', 'Ends a session.', 'Signals that reinforcement is available.'], a: 0, why: 'Hunger, or a long time without attention, are examples.' },
      { q: 'In noncontingent reinforcement, the reinforcer is delivered:', opts: ['After good behavior.', 'After problem behavior.', 'On a time schedule, whatever the student is doing.', 'Never.'], a: 2, why: 'It does not depend on behavior.' },
      { q: 'NCR reduces problem behavior mainly because:', opts: ['It punishes the behavior.', 'It teaches a new skill.', 'It tires the student.', 'The student has less reason to work for something already given freely.'], a: 3, why: 'The motivation for the behavior is lowered.' },
      { q: 'At the start, an NCR schedule is usually:', opts: ['Very thin.', 'Dense: more frequent than the behavior usually occurs.', 'Once a day.', 'Random.'], a: 1, why: 'It is thinned later.' },
      { q: 'A high-probability request sequence consists of:', opts: ['Several easy requests, each praised, followed quickly by a hard one.', 'One hard request repeated.', 'A long break.', 'A reprimand and then a request.'], a: 0, why: 'It builds momentum for following instructions.' },
      { q: 'The easy requests in the sequence must be:', opts: ['New each time.', 'Hard enough to be interesting.', 'Ones this student almost always follows.', 'Written tasks.'], a: 2, why: 'If they are not followed, there is no momentum.' },
      { q: 'A high-probability sequence should not be started:', opts: ['In the morning.', 'With praise.', 'Before a transition.', 'Straight after problem behavior.'], a: 3, why: 'It would follow the behavior with easy tasks and praise.' },
      { q: 'A good choice offers:', opts: ['One acceptable and one unacceptable option.', 'Options that are all acceptable and can all be honored.', 'A threat.', 'A question with one right answer.'], a: 1, why: 'Otherwise it is not a choice.' },
      { q: 'Demand fading means:', opts: ['Starting with few or no demands and adding them back gradually.', 'Removing all demands for good.', 'Speaking more quietly.', 'Fading prompts.'], a: 0, why: 'Demands return step by step as the student succeeds.' },
      { q: 'Interspersal means:', opts: ['Alternating teachers.', 'Spacing sessions through the day.', 'Mixing easy items among harder ones.', 'Taking turns.'], a: 2, why: 'It keeps success frequent within a hard task.' },
      { q: 'A visual schedule helps mainly by:', opts: ['Rewarding the student.', 'Punishing lateness.', 'Replacing the teacher.', 'Making what comes next predictable.'], a: 3, why: 'Uncertainty and sudden endings are common triggers.' },
      { q: 'After a warning and a timer, the activity should end:', opts: ['When the student agrees.', 'When the timer ends.', 'After two more warnings.', 'Whenever is convenient.'], a: 1, why: 'A signal that can be bargained with loses its meaning.' },
      { q: 'You see that a behavior reliably follows a particular event in the room. You:', opts: ['Report it to your supervisor.', 'Change the room yourself.', 'Ignore it.', 'Tell the other students.'], a: 0, why: 'What comes before the behavior is assessment information.' },
      { q: 'During NCR, an adult starts giving the reinforcer only when the student is behaving well. This:', opts: ['Improves NCR.', 'Is what NCR means.', 'Changes the procedure: it is no longer noncontingent.', 'Makes no difference.'], a: 2, why: 'It has become a contingent procedure, which is not what the plan specified.' },
      { q: 'Antecedent interventions are often combined with teaching a replacement behavior because:', opts: ['They are illegal alone.', 'They do not work.', 'They are too slow.', 'Prevention by itself teaches no new skill.'], a: 3, why: 'The student still needs a good way to get what the behavior got.' },
      { q: 'Problem behavior occurs while an antecedent procedure is in place. You:', opts: ['Abandon the plan.', 'Do what the plan says for that behavior.', 'Add a consequence of your own.', 'Double the NCR.'], a: 1, why: 'The plan’s response to the behavior still applies.' },
      { q: 'The best aid for running NCR on time is:', opts: ['A timer you can see or feel.', 'Your sense of time.', 'The student’s reminders.', 'The classroom clock, checked now and then.'], a: 0, why: 'Estimated intervals drift, especially when teaching gets busy.' }
    ] },
    role: [
      { t: 'NCR on a timer while teaching', setup: 'The trainer plays a student for six minutes while the trainee runs a simple task. NCR: 20 seconds of attention every 90 seconds. Once the timer sounds during “problem behavior”; the plan gives a 10-second rule.',
        steps: ['Starts the timer as the session starts.', 'Delivers at each timer, whatever the “student” is doing.', 'Gives the amount the plan says.', 'Applies the 10-second rule when the timer sounds during problem behavior.',
                'Resets the timer each time.', 'Records each delivery and any missed.'] },
      { t: 'High-probability sequence', setup: 'The trainer plays a student and supplies a list of five easy requests and one hard one. Three sequences are run.',
        steps: ['Uses requests from the list.', 'Gives three easy requests briskly, praising each.', 'Gives the hard request within 5 seconds of the last praise.', 'Praises the “student” for following the hard request.',
                'Does not start a sequence right after problem behavior.'] },
      { t: 'Choice, warning and schedule', setup: 'The trainer plays a student at the end of free play, with a visual schedule, a timer and a plan listing two choices for the next task.',
        steps: ['Gives the warning and starts the timer.', 'Ends the activity when the timer ends, calmly.', 'Shows the schedule for what is next.', 'Offers the two listed choices in a neutral tone.',
                'Honors the choice made.'] }
    ],
    roleRule: 'Met when each of the three is run once with every step in place.',
    discuss: [
      'Which of these procedures would be hardest to keep going in a busy classroom, and what would help?',
      'Think of a student you know. What tends to come just before the hardest moments of the day?',
      'When is a “choice” not a choice? How can you tell from the student’s reaction?'
    ],
    read: [
      'Vollmer, T. R., Iwata, B. A., Zarcone, J. R., Smith, R. G., & Mazaleski, J. L. (1993). The role of attention in the treatment of attention-maintained self-injurious behavior: Noncontingent reinforcement and differential reinforcement of other behavior. Journal of Applied Behavior Analysis, 26(1), 9–21.',
      'Mace, F. C., Hock, M. L., Lalli, J. S., West, B. J., Belfiore, P., Pinter, E., & Brown, D. K. (1988). Behavioral momentum in the treatment of noncompliance. Journal of Applied Behavior Analysis, 21(2), 123–141.',
      'Dunlap, G., dePerczel, M., Clarke, S., Wilson, D., Wright, S., White, R., & Gomez, A. (1994). Choice making to promote adaptive behavior for students with emotional and behavioral challenges. Journal of Applied Behavior Analysis, 27(3), 505–518.',
      'Laraway, S., Snycerski, S., Michael, J., & Poling, A. (2003). Motivating operations and terms to describe them: Some further refinements. Journal of Applied Behavior Analysis, 36(3), 407–414.'
    ]
  },

  e13: {
    aim: [
      'Say what generalization and maintenance are, and why neither happens by itself.',
      'Carry out generalization steps: other people, places, materials and instructions.',
      'Run maintenance checks without re-teaching.',
      'Report when a skill does not carry over, or carries over too far.'
    ],
    lesson: [
      { h: 'A skill that stays at the table is not finished',
        p: ['A student who asks for help only from you, only in the small room, only with your picture card, has learned something narrow. Generalization means the skill appears where it was not taught: with other people, in other places, with other materials, after other ways of asking.',
            'It can also mean new forms of the skill that were never taught: a student taught “Can I have a turn?” says “My turn next?” This is response generalization.',
            'Maintenance means the skill is still there weeks and months after teaching has stopped.'],
        key: ['Across people, places and materials.', 'New forms of the skill.', 'Over time: maintenance.'],
        check: { q: 'Zara learned to greet her teacher. She now greets the bus driver, whom nobody practiced with. This is:',
          opts: ['Maintenance', 'Generalization across people', 'Prompt dependence', 'Shaping'],
          a: 1, why: 'The skill appears with a person it was not taught with.' } },
      { h: 'It has to be planned',
        p: ['An old line in the field describes the usual approach as “train and hope”. Hoping fails often, most of all for students who learn narrowly. So generalization is written into the plan from the start, and the plan tells you what to vary and when.',
            'The main methods are easy to remember. Teach with many examples. Teach in several places and with several people. Vary the things that do not matter: your wording, your seat, the time of day. Bring things from the natural setting into teaching. Teach skills that will be rewarded naturally by the world. Thin the reinforcement toward what ordinary life provides.'],
        check: { q: 'Which is a planned method of promoting generalization?',
          opts: ['Teaching with many examples and several people.', 'Always teaching in the same seat with the same words.', 'Stopping data collection.', 'Waiting a year.'],
          a: 0, why: 'Variety in teaching is what loosens the skill from one narrow situation.' } },
      { h: 'Many examples, loosely taught',
        p: ['If every teaching trial looks the same, the student may learn the sameness. So the plan rotates examples, such as five different cups; ways of asking, such as “What is it?”, “What’s this?” and “Tell me what you see”; and incidental things like where you sit and which pen you hold.',
            'This is sometimes called training loosely. It is not the same as being careless. The things that define the right answer stay fixed and the rest is varied, on purpose and as the plan lists.'],
        check: { q: 'A plan says: “Vary the instruction among ‘Wash your hands’, ‘Go wash up’ and ‘Time to wash’.” Why?',
          opts: ['To keep the technician interested.', 'To confuse the student.', 'So the skill is not tied to one exact phrase.', 'It is a mistake in the plan.'],
          a: 2, why: 'In daily life, people will ask in many ways.' } },
      { h: 'Toward natural reinforcement',
        p: ['A skill lasts when the ordinary world rewards it. Asking politely gets the thing asked for. Reading the menu gets the food you wanted. So plans prefer skills with a natural payoff and move from added rewards, such as tokens, toward those natural ones.',
            'They also thin reinforcement and make it less predictable, because behavior that has been reinforced now and then lasts longer than behavior that was paid every time and then never. This thinning is done by the supervisor’s schedule. Your part is to follow it, and not to keep paying every time because the student likes it.'],
        check: { q: 'Why is reinforcement thinned before teaching ends?',
          opts: ['To save money.', 'To punish the student.', 'Because the student no longer needs any reinforcement.', 'So the skill will last under the leaner reinforcement of everyday life.'],
          a: 3, why: 'Skills maintained by occasional, natural reinforcement are more durable.' } },
      { h: 'Generalization and maintenance checks',
        p: ['A check, or probe, asks one question: does the skill show up here, now, without help? You set up the situation the plan describes, give no prompt and no extra reward, and record what the student does.',
            'If the skill is there, the check is recorded and that is all. If it is not, you record that, respond as the plan says, and tell your supervisor. You do not turn the check into a teaching session unless the plan tells you to. The result of the check is the point.',
            'Write down the conditions: who, where, with what. “Asked for help: yes, with the librarian, in the library, no prompt” is a result. “Yes” alone is not.'],
        check: { q: 'On a generalization check in the cafeteria, the student does not use the skill. You:',
          opts: ['Prompt it and record it as done.', 'Keep trying until it happens.', 'Record that it did not occur, with the conditions, and tell your supervisor.', 'Decide the skill is lost.'],
          a: 2, why: 'A check that is prompted no longer measures what the student does alone.' } },
      { h: 'Too little, and too much',
        p: ['Sometimes a skill does not travel: it works with you and not with the teacher, or at school and not at home. Report it with the details, because the remedy differs: more people, more places, or teaching the family, which the supervisor arranges.',
            'Sometimes it travels too far. The child who has learned “dog” calls every four-legged animal a dog; the student taught to hug family greets strangers with a hug. This is overgeneralization, and the remedy is more teaching of what does not count. Report this too, promptly where safety is involved.'],
        check: { q: 'A student who was taught to say “Hi” and hug his aide now hugs unfamiliar adults in the corridor. This is:',
          opts: ['Overgeneralization, and worth reporting promptly.', 'Good generalization: leave it.', 'Maintenance.', 'Extinction.'],
          a: 0, why: 'The skill has spread to people it should not, with a safety side to it.' } }
    ],
    examples: {
      ask: 'What does this show?',
      intro: 'Ten moments. Decide what each one shows.',
      opts: ['Generalization across people or places', 'Generalization across materials or instructions', 'Response generalization (a new form)', 'Maintenance over time'],
      items: [
        { s: 'Taught to tie laces on a practice board, Ali ties his own trainers.', a: 1, why: 'The same skill with different materials.' },
        { s: 'Taught to ask “Can I play?” with the aide, Bo asks a group of children at recess.', a: 0, why: 'New people and a new place.' },
        { s: 'Three months after teaching ended, Cat still zips her coat by herself.', a: 3, why: 'The skill has lasted.' },
        { s: 'Taught “Can I have a break?”, Dan says, “I need a minute, please.”', a: 2, why: 'A form that was never taught, with the same function.' },
        { s: 'Taught to add with counters, Eve adds using her fingers.', a: 1, why: 'Different materials.' },
        { s: 'Taught to wait his turn in the classroom, Flynn waits his turn at the dentist.', a: 0, why: 'A different place.' },
        { s: 'After the summer, Gil reads the sight words he had mastered in June.', a: 3, why: 'The skill is still there after time.' },
        { s: 'Taught to wave hello, Hope also says “Hey!” and nods to people.', a: 2, why: 'New forms of greeting.' },
        { s: 'Taught to follow “Sit down”, Ira also sits when the teacher says, “Take a seat.”', a: 1, why: 'A different instruction.' },
        { s: 'Taught to order from a picture menu at school, Jo orders at a café with her mother.', a: 0, why: 'A new place and a new person.' }
      ]
    },
    practice: {
      title: 'Take a skill out of the room',
      intro: 'Kofi, a simulated student, has mastered asking for help with the card “Help, please” in sessions with you. Read the generalization plan, then decide.',
      plan: ['Phase 1: practice with two other adults (the aide, the librarian) in the session room.', 'Phase 2: in the classroom and the library, during ordinary tasks. Reinforcement: the help itself, and praise about every third time.', 'Vary what he needs help with: a tight lid, a high shelf, a hard zip, a stuck drawer.', 'Checks: once a week in a new place, no prompt. Record who, where, what, and what he did.', 'If he does not ask on a check: wait 10 seconds, help him without comment, record “did not ask”.'],
      steps: [
        { t: 'Phase 1', see: 'The aide is to run today’s practice. You are tempted to stay beside Kofi and nod when he should ask.', opts: ['Stay close and nod.', 'Step back, out of his line of sight, and let the aide run it.', 'Run it yourself and say the aide did.'], a: 1, why: 'The aim is that he asks the aide. Your nod would be a prompt, and the skill would still depend on you.' },
        { t: 'Phase 1', see: 'Kofi asks the aide for help with the lid. She says, “Good asking!”, gives him a token and opens the lid.', opts: ['Fine: more reinforcement is better.', 'Mention to the aide, and to your supervisor, that this phase uses the help itself as the reinforcer.', 'Take the token away.'], a: 1, why: 'The plan is moving toward natural reinforcement. Extra tokens keep the skill tied to them.' },
        { t: 'Phase 2', see: 'In the classroom you have used the tight lid three times running.', opts: ['Keep using it: it works.', 'Switch to another of the listed needs.', 'Skip practice today.'], a: 1, why: 'Varied needs keep the skill from becoming “how I get lids opened”.' },
        { t: 'Phase 2', see: 'Kofi asks for help. It is the second time since you last praised him.', opts: ['Help him, without added praise this time.', 'Help him and praise him every time.', 'Do not help: he has had enough help.'], a: 0, why: 'The help always follows. The praise has been thinned to about every third time.' },
        { t: 'Weekly check', see: 'In the gym, Kofi’s shoelace is knotted. He looks at it and then at the PE teacher, and does not use his card. Ten seconds pass.', opts: ['Say, “Use your card, Kofi.”', 'Help him without comment and record “did not ask: gym, PE teacher, knotted lace”.', 'Record that he asked with his eyes.'], a: 1, why: 'A check is not prompted. The look is worth a note, and it is not the skill.' },
        { t: 'After the check', see: 'What do you do with the result?', opts: ['Start teaching in the gym tomorrow on your own.', 'Tell your supervisor: it worked in the classroom and library, not in the gym with the PE teacher.', 'Decide he cannot generalize.'], a: 1, why: 'The supervisor decides whether to add the gym, or the PE teacher, to the teaching.' },
        { t: 'A surprise', see: 'A week later, with no card in reach, Kofi tugs a classmate’s sleeve and says, “Help?”', opts: ['Tell him to fetch his card.', 'Make sure the classmate, or you, helps him, and record it as a new form.', 'Ignore it: it was not the trained response.'], a: 1, why: 'A new form with the same purpose is response generalization, and it needs to pay off.' },
        { t: 'Three months on', see: 'The plan asks for a maintenance check. Kofi asks the lunch supervisor for help without hesitation.', opts: ['Record it with who, where and what, and report that the skill has been maintained.', 'Give him ten tokens.', 'Re-teach the skill to be safe.'], a: 0, why: 'The check has answered its question. Nothing more is needed than the record.' }
      ]
    },
    quiz: { pass: 80, draw: 10, items: [
      { q: 'Stimulus generalization means the skill occurs:', opts: ['Only with the teaching materials.', 'With people, places or materials other than those used in teaching.', 'Less often.', 'Only when prompted.'], a: 1, why: 'It appears in new situations.' },
      { q: 'Response generalization means:', opts: ['The student shows untaught forms of the skill that do the same job.', 'The skill is forgotten.', 'The skill occurs in a new room.', 'The response is faster.'], a: 0, why: 'New forms, the same function.' },
      { q: 'Maintenance means the skill:', opts: ['Needs daily teaching.', 'Appears with new people.', 'Continues after teaching has stopped.', 'Is being acquired.'], a: 2, why: 'It lasts over time.' },
      { q: '“Train and hope” describes:', opts: ['The recommended method.', 'A reinforcement schedule.', 'A probe.', 'Teaching in one situation and hoping the skill spreads.'], a: 3, why: 'It often fails, which is why generalization is planned.' },
      { q: 'Teaching with many different examples helps because:', opts: ['It takes longer.', 'The student learns what the examples share, not one item.', 'It uses more cards.', 'It avoids data.'], a: 1, why: 'It is one of the main methods for generalization.' },
      { q: '“Training loosely” means:', opts: ['Varying the things that do not define the right answer.', 'Not following the plan.', 'Using no reinforcement.', 'Teaching without data.'], a: 0, why: 'Wording, seat and time of day are varied on purpose.' },
      { q: 'A skill is most likely to last if it:', opts: ['Is rewarded only with tokens.', 'Is practiced only at the table.', 'Meets natural reinforcement in everyday life.', 'Is never checked.'], a: 2, why: 'The world keeps paying for it.' },
      { q: 'During a generalization or maintenance check you give:', opts: ['Full prompts.', 'A reminder first.', 'Extra reinforcers.', 'No prompt.'], a: 3, why: 'The check measures what the student does unaided.' },
      { q: 'A check is recorded with:', opts: ['“Yes” or “no” only.', 'Who was there, where, with what, and what the student did.', 'The weather.', 'Nothing, if it went well.'], a: 1, why: 'The conditions are what make the result useful.' },
      { q: 'A skill appears with the technician and not with the teacher. You:', opts: ['Tell your supervisor, with the details.', 'Blame the teacher.', 'Start a new program.', 'Stop teaching the skill.'], a: 0, why: 'The supervisor can add people or settings to the teaching.' },
      { q: 'Calling every round fruit an “apple” is an example of:', opts: ['Maintenance', 'Prompt dependence', 'Overgeneralization', 'Extinction'], a: 2, why: 'The response has spread to things it should not include.' },
      { q: 'Reinforcement is made thinner and less predictable so that:', opts: ['The student gives up.', 'Staff have less to do.', 'Data are easier.', 'The skill resembles, and survives, everyday conditions.'], a: 3, why: 'Occasionally reinforced behavior lasts longer.' },
      { q: 'When another adult runs a generalization session, you should:', opts: ['Sit beside the student and help.', 'Stay out of the way, so the student responds to that adult.', 'Whisper prompts.', 'Take over if it goes slowly.'], a: 1, why: 'Otherwise the skill still depends on you.' },
      { q: 'Who decides when a skill moves from acquisition to maintenance?', opts: ['The supervisor, by the plan’s criterion.', 'The technician.', 'The student.', 'The calendar.'], a: 0, why: 'You report that the criterion has been met.' }
    ] },
    role: [
      { t: 'Hand a skill to another adult', setup: 'The trainer plays a student who has a skill with the trainee only. A helper (or the trainer in a second role) plays a new adult. The trainee briefs the new adult from the plan and then steps back.',
        steps: ['Tells the new adult what the student will do and what follows it.', 'Says what not to add (extra prompts or rewards).', 'Steps out of the student’s line of sight.', 'Gives no nod, look or word during the practice.',
                'Records who, where, what and the result.'] },
      { t: 'A check that fails', setup: 'The trainer plays a student who does not use the skill in a new place. The plan’s rule for a failed check is on a card.',
        steps: ['Sets up the situation as described, without a prompt.', 'Waits the set time.', 'Responds as the card says, without comment.', 'Records “did not occur” with the conditions.', 'Says what they would report, and does not start re-teaching.'] }
    ],
    roleRule: 'Met when each role-play is done once with every step in place.',
    discuss: [
      'Which of your students’ skills live only in one room or with one person?',
      'What makes it hard to step back when another adult takes over?',
      'Think of a skill you learned and still have. What has kept it going?'
    ],
    read: [
      'Stokes, T. F., & Baer, D. M. (1977). An implicit technology of generalization. Journal of Applied Behavior Analysis, 10(2), 349–367.',
      'Stokes, T. F., & Osnes, P. G. (1989). An operant pursuit of generalization. Behavior Therapy, 20(3), 337–355.',
      'Cooper, J. O., Heron, T. E., & Heward, W. L. (2020). Applied behavior analysis (3rd ed.). Pearson. The chapter on generalization and maintenance of behavior change.'
    ]
  }
});
